package cn.shiguang.qwenpocket;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.io.File;
/** Shared typography and quieter surfaces for home, composer and conversation. */
final class ChatDesign {
    static int examplePage=0;
    static GradientDrawable surface(MainActivity a,int color,int radius){GradientDrawable bg=a.shape(color,radius);bg.setStroke(a.dp(1),0xffe0e8e2);return bg;}
    static void build(MainActivity a){
        a.root=a.column();a.root.setBackgroundColor(MainActivity.BG);a.setContentView(a.root);a.root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(a.dp(20),i.getSystemWindowInsetTop()+a.dp(4),a.dp(20),i.getSystemWindowInsetBottom()+a.dp(8));return i;});
        LinearLayout head=a.row();a.settings=a.button("☰",false);a.settings.setTextSize(21);a.settings.setBackgroundColor(Color.TRANSPARENT);a.settings.setContentDescription("打开对话记录");a.settings.setOnClickListener(v->a.showHistory());head.addView(a.settings,new LinearLayout.LayoutParams(a.dp(44),a.dp(48)));
        TextView brand=a.text("观知",20,MainActivity.INK);brand.setTypeface(null,Typeface.BOLD);brand.setGravity(Gravity.CENTER);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));a.fresh=a.button("＋",false);a.fresh.setTextSize(25);a.fresh.setBackgroundColor(Color.TRANSPARENT);a.fresh.setContentDescription("新建对话");a.fresh.setOnClickListener(v->a.newChat());head.addView(a.fresh,new LinearLayout.LayoutParams(a.dp(44),a.dp(48)));a.root.addView(head);
        a.status=a.text("正在准备本地模型",11,MainActivity.GREEN);a.status.setGravity(Gravity.CENTER);a.status.setPadding(0,a.dp(3),0,a.dp(8));a.status.setOnClickListener(v->a.showSpeedProfiles());a.root.addView(a.status);
        a.detail=a.text("首次启动正在准备量化模型",12,MainActivity.MUTED);a.detail.setGravity(Gravity.CENTER);a.root.addView(a.detail);a.progress=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);a.progress.setIndeterminate(true);a.root.addView(a.progress,new LinearLayout.LayoutParams(-1,a.dp(2)));
        a.scroll=new ScrollView(a);a.scroll.setFillViewport(true);a.scroll.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN)a.followOutput=false;else if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)a.followOutput=a.isNearBottom();return false;});a.scroll.setOnScrollChangeListener((v,x,y,ox,oy)->{if(a.busy&&y<oy)a.followOutput=false;});a.scroll.setClipToPadding(false);a.timeline=a.column();a.timeline.setPadding(0,a.dp(18),0,a.dp(16));a.scroll.addView(a.timeline);a.root.addView(a.scroll,new LinearLayout.LayoutParams(-1,0,1));
        a.composer=a.column();a.composer.setPadding(a.dp(14),a.dp(10),a.dp(10),a.dp(8));a.composer.setBackground(surface(a,Color.WHITE,24));a.root.addView(a.composer);
        a.imageRow=a.row();a.thumbnail=new ImageView(a);a.thumbnail.setScaleType(ImageView.ScaleType.CENTER_CROP);a.thumbnail.setOnClickListener(v->a.openWorkbench(a.pendingImage));a.imageRow.addView(a.thumbnail,new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));a.imageLabel=a.text("图片已添加",12,MainActivity.MUTED);a.imageLabel.setPadding(a.dp(10),0,0,0);a.imageRow.addView(a.imageLabel,new LinearLayout.LayoutParams(0,-2,1));Button remove=a.button("×",false);remove.setBackgroundColor(Color.TRANSPARENT);remove.setContentDescription("移除图片");remove.setOnClickListener(v->{if(a.busy)return;a.pendingImage="";a.pendingEvidence="";a.refreshAttachment();a.saveChat();});a.imageRow.addView(remove);a.imageRow.setVisibility(View.GONE);a.composer.addView(a.imageRow);
        a.attachmentNote=a.text("",11,MainActivity.GREEN);a.attachmentNote.setVisibility(View.GONE);a.attachmentNote.setOnClickListener(v->{if(a.busy)return;if(a.pendingEvidence.isEmpty()){if(a.tools.useLibrary)a.tools.library();else{AppPages pages=new AppPages(a);pages.open(()->pages.taskExamples(a.selectedTask));}return;}new AlertDialog.Builder(a).setTitle("附加文字").setMessage(a.pendingEvidence).setPositiveButton("保留",null).setNeutralButton("清除",(d,w)->{a.pendingEvidence="";a.refreshAttachment();a.saveChat();}).show();});a.composer.addView(a.attachmentNote);
        a.input=new EditText(a);a.input.setTextSize(16);a.input.setTextColor(MainActivity.INK);a.input.setHintTextColor(MainActivity.MUTED);a.input.setHint("写下问题，或添加一张图片");a.input.setBackgroundColor(Color.TRANSPARENT);a.input.setMinLines(1);a.input.setMaxLines(5);a.input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);a.composer.addView(a.input,new LinearLayout.LayoutParams(-1,-2));
        LinearLayout actions=a.row();a.camera=a.button("拍照",false);a.camera.setBackgroundColor(Color.TRANSPARENT);a.camera.setOnClickListener(v->a.chooseImage(true));actions.addView(a.camera);a.attach=a.button("相册",false);a.attach.setBackgroundColor(Color.TRANSPARENT);a.attach.setOnClickListener(v->a.chooseImage(false));actions.addView(a.attach);a.taskButton=a.button("任务",false);a.taskButton.setBackgroundColor(Color.TRANSPARENT);a.taskButton.setOnClickListener(v->{if(!a.busy)a.tools.tasks();});actions.addView(a.taskButton);a.webToggle=a.button("联网",false);a.webToggle.setPadding(a.dp(8),0,a.dp(8),0);a.webToggle.setTextSize(12);a.webToggle.setOnClickListener(v->a.toggleWeb());actions.addView(a.webToggle);for(Button b:new Button[]{a.camera,a.attach,a.taskButton}){b.setPadding(a.dp(7),0,a.dp(7),0);b.setTextSize(12);}actions.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));a.send=a.button("↑",true);a.send.setTextSize(21);a.send.setContentDescription("发送问题");a.send.setEnabled(false);a.send.setOnClickListener(v->{if(a.busy)a.stopReply();else a.startReply();});actions.addView(a.send,new LinearLayout.LayoutParams(a.dp(48),a.dp(44)));a.composer.addView(actions);
        a.metrics=a.text("本地模型推理 · 可按需开启联网搜索",10,MainActivity.MUTED);a.metrics.setGravity(Gravity.CENTER);a.metrics.setPadding(0,a.dp(8),0,0);a.root.addView(a.metrics);a.refreshWeb();
    }
    static void welcome(MainActivity a){
        LinearLayout welcome=a.column();welcome.setPadding(a.dp(4),a.dp(12),a.dp(4),a.dp(8));TextView eyebrow=a.text("你的本地多模态助手",12,MainActivity.GREEN);welcome.addView(eyebrow);TextView title=a.text("今天，想弄懂什么？",27,MainActivity.INK);title.setTypeface(null,Typeface.BOLD);title.setPadding(0,a.dp(12),0,a.dp(10));welcome.addView(title);TextView subtitle=a.text("一张图，一个问题。\n由微调后的 Qwen3.5-0.8B 在手机上分析。",13,MainActivity.MUTED);subtitle.setLineSpacing(a.dp(5),1);welcome.addView(subtitle);
        String[] labels={"读图计算","看图解题","识别提取","趣味联想"},subs={"账单 · 表格 · 数值","空间 · 逻辑 · 专业题","文字 · 细节 · 代码","成语 · 画面隐喻"};
        for(int r=0;r<2;r++){LinearLayout row=a.row();for(int c=0;c<2;c++){int n=r*2+c;LinearLayout box=a.column();box.setPadding(a.dp(14),a.dp(16),a.dp(10),a.dp(16));box.setBackground(surface(a,Color.WHITE,18));TextView name=a.text(labels[n]+"  ↗",15,MainActivity.INK);name.setTypeface(null,Typeface.BOLD);box.addView(name);TextView sub=a.text(subs[n],11,MainActivity.MUTED);sub.setPadding(0,a.dp(7),0,0);box.addView(sub);box.setFocusable(true);box.setOnClickListener(v->a.tools.taskGroup(n+1));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(c==0?0:a.dp(5),a.dp(r==0?22:10),c==0?a.dp(5):0,0);row.addView(box,lp);}welcome.addView(row);}
        LinearLayout label=a.row();TextView heading=a.text("从一个实例开始",14,MainActivity.INK);heading.setTypeface(null,Typeface.BOLD);label.addView(heading,new LinearLayout.LayoutParams(0,-2,1));Button next=a.button("换一组",false);next.setBackgroundColor(Color.TRANSPARENT);next.setTextSize(12);next.setOnClickListener(v->{examplePage=(examplePage+1)%3;a.renderChat();});label.addView(next);LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.topMargin=a.dp(18);welcome.addView(label,space);
        int[][] choices={{1,7},{8,6},{3,0}};for(int task:choices[examplePage]){TaskExamples.Example e=TaskExamples.get(task)[0];TextView item=a.text(e.title+"    ↗",14,MainActivity.MUTED);item.setPadding(a.dp(2),a.dp(12),0,a.dp(12));item.setOnClickListener(v->a.useTask(task,e.prompt,e.image,false,null,""));item.setFocusable(true);welcome.addView(item);}a.timeline.addView(welcome);
    }
    static TextView bubble(MainActivity a,MainActivity.Message m){
        boolean user="user".equals(m.role);LinearLayout card=a.column();card.setPadding(user?a.dp(16):0,user?a.dp(12):a.dp(5),user?a.dp(16):0,a.dp(12));if(user)card.setBackground(a.shape(0xffe8f0ea,20));
        LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(user?-2:-1,-2);lp.gravity=user?Gravity.END:Gravity.START;lp.setMargins(user?a.dp(38):0,0,0,a.dp(user?22:26));a.timeline.addView(card,lp);
        if(!user){LinearLayout identity=a.row();ImageView logo=new ImageView(a);logo.setImageResource(R.drawable.ic_launcher);identity.addView(logo,new LinearLayout.LayoutParams(a.dp(24),a.dp(24)));TextView name=a.text("观知  ·  本地模型",12,MainActivity.MUTED);name.setPadding(a.dp(9),0,0,0);identity.addView(name);card.addView(identity);}
        if(!m.image.isEmpty()&&new File(m.image).exists()){ImageView image=new ImageView(a);BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=4;image.setImageBitmap(BitmapFactory.decodeFile(m.image,options));image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setOnClickListener(v->a.openWorkbench(m.image));card.addView(image,new LinearLayout.LayoutParams(Math.min(a.dp(240),a.getResources().getDisplayMetrics().widthPixels-a.dp(112)),a.dp(180)));}
        TextView body=a.text(m.text,16,MainActivity.INK);body.setTextIsSelectable(true);body.setLineSpacing(a.dp(5),1);body.setPadding(0,user?0:a.dp(14),0,0);if(user)body.setMaxWidth(a.getResources().getDisplayMetrics().widthPixels-a.dp(110));card.addView(body);if("pending".equals(m.state))a.streamingOutput=body;
        if(!user&&("pending".equals(m.state)||!m.text.isEmpty())){RichAnswerView answer=new RichAnswerView(a,m.text);answer.setPadding(0,a.dp(12),0,0);card.addView(answer,new LinearLayout.LayoutParams(-1,-2));if("pending".equals(m.state)){a.streamingRich=answer;answer.heightChanged=()->{if(a.followOutput&&a.streamingRich==answer)a.scroll.post(()->{if(a.followOutput&&a.streamingRich==answer)a.scroll.fullScroll(View.FOCUS_DOWN);});};answer.setVisibility(View.GONE);}else body.setVisibility(View.GONE);}
        if(!user&&!"pending".equals(m.state)){
            if(!m.stopNote.isEmpty())card.addView(a.text(m.stopNote,12,MainActivity.GREEN));
            if(!m.sources.isEmpty()){Button refs=a.button("网页来源 · "+m.sources.size(),false);refs.setOnClickListener(v->{String[] labels=new String[m.sources.size()];for(int i=0;i<labels.length;i++)labels[i]="["+(i+1)+"] "+m.sources.get(i).title;new AlertDialog.Builder(a).setTitle((m.searchFallback?"原问题检索：":"本地检索词：")+m.searchQuery).setItems(labels,(d,i)->a.openSource(m.sources.get(i))).setPositiveButton("返回",null).show();});card.addView(refs);}
            LinearLayout actions=a.row();Button copy=a.button("复制",false);copy.setBackgroundColor(Color.TRANSPARENT);copy.setOnClickListener(v->{((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("回答",m.text));a.toast("已复制");});actions.addView(copy);
            if(a.messages.indexOf(m)==a.messages.size()-1){Button retry=a.button("重答",false);retry.setBackgroundColor(Color.TRANSPARENT);retry.setOnClickListener(v->a.retryLast());actions.addView(retry);}
            Button more=a.button("···",false);more.setBackgroundColor(Color.TRANSPARENT);more.setContentDescription("回答详情与反馈");more.setOnClickListener(v->{if(a.busy)return;PopupMenu menu=new PopupMenu(a,more);for(String op:new String[]{"查看输入与依据","记录反馈","对照评测","运行详情"})menu.getMenu().add(op);menu.setOnMenuItemClickListener(item->{String op=item.getTitle().toString();MainActivity.Message q=a.tools.question(m);if(op.equals("查看输入与依据")&&q!=null)a.tools.evidence(q,m);else if(op.equals("记录反馈"))a.tools.feedback(m);else if(op.equals("对照评测")&&q!=null)a.tools.compare(q,m);else a.tools.showText("运行详情",m.modelInfo+"\n"+m.timing+"\n"+m.stopNote+(m.sources.isEmpty()?"":"\n网页总结由本地模型生成；可在来源中查看检索词和资料。"));return true;});menu.show();});actions.addView(more);card.addView(actions);
        }return body;
    }
}
